import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('review PR', true), '[x] review PR');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('write docs', false), '[ ] write docs');
});

test('preserves exact task name including whitespace or symbols', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('   ', false), '[ ]    ');
  assert.equal(taskLabel('[x] already prefixed', true), '[x] [x] already prefixed');
});

